use chrono::Utc;
use rusqlite::{params,Connection,OptionalExtension};
use rusted_core::{Settings,Workspace};
use std::path::{Path,PathBuf};
use thiserror::Error;
#[derive(Debug,Error)]pub enum DbError{#[error("database: {0}")]Sql(#[from]rusqlite::Error),#[error("state encoding: {0}")]Json(#[from]serde_json::Error),#[error("no local application data directory is available")]NoDataDirectory}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Bookmark{pub path:PathBuf,pub label:String,pub position:i64,pub section:String}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Tag{pub path:PathBuf,pub name:String,pub color:String}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Profile{pub name:String,pub workspace:Workspace,pub settings:Settings}
pub struct Database{connection:Connection}
impl Database{
    pub fn open_default()->Result<Self,DbError>{let project=directories::ProjectDirs::from("com","Rusted","Rusted").ok_or(DbError::NoDataDirectory)?;let dir=project.data_local_dir();std::fs::create_dir_all(dir).map_err(rusqlite::Error::ToSqlConversionFailure)?;Self::open(&dir.join("rusted.db"))}
    pub fn open(path:&Path)->Result<Self,DbError>{Self::init(Connection::open(path)?)}
    pub fn in_memory()->Result<Self,DbError>{Self::init(Connection::open_in_memory()?)}
    fn init(connection:Connection)->Result<Self,DbError>{connection.execute_batch("PRAGMA journal_mode=WAL;PRAGMA foreign_keys=ON;PRAGMA busy_timeout=3000;CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS bookmarks(path TEXT PRIMARY KEY,label TEXT NOT NULL,position INTEGER NOT NULL,section TEXT NOT NULL DEFAULT 'Pinned');CREATE TABLE IF NOT EXISTS tags(path TEXT NOT NULL,name TEXT NOT NULL,color TEXT NOT NULL,PRIMARY KEY(path,name));CREATE TABLE IF NOT EXISTS recent_locations(path TEXT PRIMARY KEY,visited_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS recent_files(path TEXT PRIMARY KEY,opened_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS sessions(name TEXT PRIMARY KEY,workspace TEXT NOT NULL,updated_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS profiles(name TEXT PRIMARY KEY,workspace TEXT NOT NULL,settings TEXT NOT NULL);")?;Ok(Self{connection})}
    pub fn save_settings(&self,settings:&Settings)->Result<(),DbError>{self.set_json("settings",settings)?;Ok(())}
    pub fn load_settings(&self)->Result<Option<Settings>,DbError>{self.get_json("settings")}
    pub fn pin(&self,path:&Path,label:&str,section:&str)->Result<(),DbError>{let position=self.connection.query_row("SELECT COALESCE(MAX(position),-1)+1 FROM bookmarks WHERE section=?1",[section],|r|r.get::<_,i64>(0))?;self.connection.execute("INSERT INTO bookmarks(path,label,position,section) VALUES(?1,?2,?3,?4) ON CONFLICT(path) DO UPDATE SET label=excluded.label,section=excluded.section",params![path.to_string_lossy(),label,position,section])?;Ok(())}
    pub fn unpin(&self,path:&Path)->Result<(),DbError>{self.connection.execute("DELETE FROM bookmarks WHERE path=?1",[path.to_string_lossy()])?;Ok(())}
    pub fn move_bookmark(&self,path:&Path,position:i64)->Result<(),DbError>{self.connection.execute("UPDATE bookmarks SET position=?2 WHERE path=?1",params![path.to_string_lossy(),position])?;Ok(())}
    pub fn bookmarks(&self)->Result<Vec<Bookmark>,DbError>{let mut s=self.connection.prepare("SELECT path,label,position,section FROM bookmarks ORDER BY section,position,label")?;Ok(s.query_map([],|r|Ok(Bookmark{path:r.get::<_,String>(0)?.into(),label:r.get(1)?,position:r.get(2)?,section:r.get(3)?}))?.collect::<Result<_,_>>()?)}
    pub fn tag(&self,path:&Path,name:&str,color:&str)->Result<(),DbError>{self.connection.execute("INSERT INTO tags(path,name,color) VALUES(?1,?2,?3) ON CONFLICT(path,name) DO UPDATE SET color=excluded.color",params![path.to_string_lossy(),name,color])?;Ok(())}
    pub fn untag(&self,path:&Path,name:&str)->Result<(),DbError>{self.connection.execute("DELETE FROM tags WHERE path=?1 AND name=?2",params![path.to_string_lossy(),name])?;Ok(())}
    pub fn tags(&self,filter:Option<&str>)->Result<Vec<Tag>,DbError>{let sql="SELECT path,name,color FROM tags WHERE (?1 IS NULL OR name=?1) ORDER BY name,path";let mut s=self.connection.prepare(sql)?;Ok(s.query_map([filter],|r|Ok(Tag{path:r.get::<_,String>(0)?.into(),name:r.get(1)?,color:r.get(2)?}))?.collect::<Result<_,_>>()?)}
    pub fn visit(&self,path:&Path)->Result<(),DbError>{self.connection.execute("INSERT INTO recent_locations(path,visited_at) VALUES(?1,?2) ON CONFLICT(path) DO UPDATE SET visited_at=excluded.visited_at",params![path.to_string_lossy(),Utc::now().timestamp()])?;self.trim_recent("recent_locations","visited_at")?;Ok(())}
    pub fn opened_file(&self,path:&Path)->Result<(),DbError>{self.connection.execute("INSERT INTO recent_files(path,opened_at) VALUES(?1,?2) ON CONFLICT(path) DO UPDATE SET opened_at=excluded.opened_at",params![path.to_string_lossy(),Utc::now().timestamp()])?;self.trim_recent("recent_files","opened_at")?;Ok(())}
    fn trim_recent(&self,table:&str,column:&str)->Result<(),DbError>{self.connection.execute(&format!("DELETE FROM {table} WHERE path NOT IN (SELECT path FROM {table} ORDER BY {column} DESC LIMIT 500)"),[])?;Ok(())}
    pub fn recent_locations(&self,limit:usize)->Result<Vec<PathBuf>,DbError>{let mut s=self.connection.prepare("SELECT path FROM recent_locations ORDER BY visited_at DESC LIMIT ?1")?;Ok(s.query_map([limit as i64],|r|Ok(PathBuf::from(r.get::<_,String>(0)?)))?.collect::<Result<_,_>>()?)}
    pub fn save_session(&self,name:&str,workspace:&Workspace)->Result<(),DbError>{self.connection.execute("INSERT INTO sessions(name,workspace,updated_at) VALUES(?1,?2,?3) ON CONFLICT(name) DO UPDATE SET workspace=excluded.workspace,updated_at=excluded.updated_at",params![name,serde_json::to_string(workspace)?,Utc::now().timestamp()])?;Ok(())}
    pub fn load_session(&self,name:&str)->Result<Option<Workspace>,DbError>{let value=self.connection.query_row("SELECT workspace FROM sessions WHERE name=?1",[name],|r|r.get::<_,String>(0)).optional()?;value.map(|v|serde_json::from_str(&v).map_err(Into::into)).transpose()}
    pub fn save_profile(&self,profile:&Profile)->Result<(),DbError>{self.connection.execute("INSERT INTO profiles(name,workspace,settings) VALUES(?1,?2,?3) ON CONFLICT(name) DO UPDATE SET workspace=excluded.workspace,settings=excluded.settings",params![profile.name,serde_json::to_string(&profile.workspace)?,serde_json::to_string(&profile.settings)?])?;Ok(())}
    pub fn load_profile(&self,name:&str)->Result<Option<Profile>,DbError>{let row=self.connection.query_row("SELECT workspace,settings FROM profiles WHERE name=?1",[name],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).optional()?;row.map(|(w,s)|Ok(Profile{name:name.into(),workspace:serde_json::from_str(&w)?,settings:serde_json::from_str(&s)?})).transpose()}
    fn set_json<T:serde::Serialize>(&self,key:&str,value:&T)->Result<(),DbError>{self.connection.execute("INSERT INTO settings(key,value) VALUES(?1,?2) ON CONFLICT(key) DO UPDATE SET value=excluded.value",params![key,serde_json::to_string(value)?])?;Ok(())}
    fn get_json<T:serde::de::DeserializeOwned>(&self,key:&str)->Result<Option<T>,DbError>{let value=self.connection.query_row("SELECT value FROM settings WHERE key=?1",[key],|r|r.get::<_,String>(0)).optional()?;value.map(|v|serde_json::from_str(&v).map_err(Into::into)).transpose()}
}
